    Vars::RefOut<float> out_flow_pub;
    Vars::RefOut<float> out_total;
    Vars::RefOut<bool>  leak;
    Vars::RefOut<bool>  pressure;

    /** @} */

private:

    /** @name VAR - function blocks
     *  @{ */

    Plc::Ewma       flow_avg;   ///< the loop, averaged over irr_out_avg_ms
    Plc::Deadband   flow_band;  ///< ...and how far it must move to be written
    Plc::Derivative in_rate;    ///< litres -> Lpm, over a window
    Plc::Integral   out_meter;  ///< Lpm -> litres

    /** @} */

    /** @name VAR - what this law remembers
     *  @{ */

    float    _in_base_L = 0.0f;    ///< Where the inlet counter stood when this run adopted it: the pulse counter restarts at boot and the published total does not, so the total is the retained value plus what has been counted since.
    uint32_t _in_base_pulses = 0;

